//! `cargo xtask bindings [--check]`: the C header, and the Kotlin and Swift
//! bindings, from `orb-capi`'s Diplomat bridge. Each output
//! directory holds only generated files; `--check` fails when they're stale.
//!
//! `cargo xtask bindings --test` runs `diplomat-swift-kotlin`'s compile-and-
//! run tests (`swiftc`, a JDK and `kotlinc` from `mise.toml`), then the C and
//! Kotlin smoke tests against `cargo xtask capi`'s library and, on macOS, the
//! Swift one (`cargo xtask apple --test`).

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;

const ENTRY: &str = "crates/orb-capi/src/lib.rs";
/// Diplomat's headers and the `orbis.h` umbrella.
pub(crate) const C_DIR: &str = "crates/orb-capi/include";
const KOTLIN_DIR: &str = "hosts/android/orbis/src/generated/kotlin";
const JNI_DIR: &str = "hosts/android/orbis/src/generated/jni";
const SWIFT_DIR: &str = "hosts/apple/Sources/Orbis/Generated";

pub(crate) fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .canonicalize()
        .expect("the repository exists")
}

pub(crate) fn run(args: &[String]) -> Result<(), String> {
    match args.first().map(String::as_str) {
        None => generate(false),
        Some("--check") => generate(true),
        Some("--test") => test(),
        Some(other) => Err(format!("bindings: unknown argument {other}")),
    }
}

/// Every generated file, by path from the repository root.
fn outputs() -> Result<BTreeMap<String, String>, String> {
    let root = root();
    let entry = root.join(ENTRY);
    let mut out = BTreeMap::new();

    let scratch = std::env::temp_dir().join(format!("orbis-bindings-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&scratch);
    diplomat_tool::r#gen(
        &entry,
        "c",
        &scratch,
        &Default::default(),
        Default::default(),
        true,
    )
    .map_err(|e| format!("C header: {e}"))?;
    let mut headers = Vec::new();
    for file in std::fs::read_dir(&scratch).map_err(|e| e.to_string())? {
        let file = file.map_err(|e| e.to_string())?;
        let name = file.file_name().to_string_lossy().into_owned();
        let text = std::fs::read_to_string(file.path()).map_err(|e| e.to_string())?;
        if !name.ends_with(".d.h") && name != "diplomat_runtime.h" {
            headers.push(name.clone());
        }
        out.insert(format!("{C_DIR}/{name}"), text);
    }
    std::fs::remove_dir_all(&scratch).map_err(|e| e.to_string())?;
    headers.sort();
    let mut umbrella = String::from(
        "/* Generated by `cargo xtask bindings`. Do not edit.\n *\n * The Orbis C ABI, 0.x: every type and function.\n */\n\n#ifndef ORBIS_H\n#define ORBIS_H\n\n",
    );
    for h in &headers {
        umbrella += &format!("#include \"{h}\"\n");
    }
    umbrella += "\n#endif /* ORBIS_H */\n";
    out.insert(format!("{C_DIR}/orbis.h"), umbrella);

    let errors = |e: Vec<String>| e.join("\n");
    let kotlin = diplomat_swift_kotlin::kotlin(
        &entry,
        &diplomat_swift_kotlin::KotlinConfig {
            package: "dev.orbis".into(),
            library: "orbis".into(),
            native_object: "OrbisNative".into(),
            c_headers: vec!["orbis.h".into()],
        },
    )
    .map_err(errors)?;
    for (path, text) in kotlin {
        let path = match path.split_once('/') {
            Some(("kotlin", rest)) => format!("{KOTLIN_DIR}/{rest}"),
            Some(("jni", rest)) => format!("{JNI_DIR}/{rest}"),
            _ => return Err(format!("unexpected Kotlin output {path}")),
        };
        out.insert(path, text);
    }
    let swift = diplomat_swift_kotlin::swift(
        &entry,
        &diplomat_swift_kotlin::SwiftConfig {
            c_module: "OrbisC".into(),
        },
    )
    .map_err(errors)?;
    for (path, text) in swift {
        out.insert(format!("{SWIFT_DIR}/{path}"), text);
    }
    Ok(out)
}

fn generate(check: bool) -> Result<(), String> {
    let root = root();
    let outputs = outputs()?;
    let mut existing = Vec::new();
    for dir in [C_DIR, KOTLIN_DIR, JNI_DIR, SWIFT_DIR] {
        files_under(&root, &root.join(dir), &mut existing);
    }
    let stale: Vec<&String> = existing
        .iter()
        .filter(|p| !outputs.contains_key(*p))
        .collect();
    let changed: Vec<&String> = outputs
        .iter()
        .filter(|(path, text)| {
            std::fs::read_to_string(root.join(path)).ok().as_ref() != Some(*text)
        })
        .map(|(path, _)| path)
        .collect();
    if check {
        if stale.is_empty() && changed.is_empty() {
            eprintln!("bindings: {} generated files up to date", outputs.len());
            return Ok(());
        }
        return Err(format!(
            "bindings are stale (run `cargo xtask bindings`): {}",
            changed
                .iter()
                .chain(&stale)
                .map(|p| p.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    for path in stale {
        std::fs::remove_file(root.join(path)).map_err(|e| format!("{path}: {e}"))?;
    }
    for path in &changed {
        let file = root.join(path);
        std::fs::create_dir_all(file.parent().expect("files have parents"))
            .map_err(|e| e.to_string())?;
        std::fs::write(&file, &outputs[*path]).map_err(|e| format!("{path}: {e}"))?;
    }
    let lines: usize = outputs.values().map(|t| t.lines().count()).sum();
    eprintln!(
        "bindings: {} files ({lines} lines), {} changed",
        outputs.len(),
        changed.len()
    );
    Ok(())
}

fn files_under(root: &Path, dir: &Path, out: &mut Vec<String>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            files_under(root, &path, out);
        } else if let Ok(rel) = path.strip_prefix(root) {
            out.push(rel.to_string_lossy().replace('\\', "/"));
        }
    }
}

/// The emitters' compile-and-run tests, then the smoke tests.
fn test() -> Result<(), String> {
    let mut command = Command::new(env!("CARGO"));
    command.args([
        "test",
        "-p",
        "diplomat-swift-kotlin",
        "--test",
        "run",
        "--",
        "--ignored",
        "--nocapture",
    ]);
    eprintln!("$ {command:?}");
    let status = command.status().map_err(|e| e.to_string())?;
    if !status.success() {
        return Err("binding run tests failed".into());
    }
    crate::capi::smoke(&crate::capi::build()?)?;
    if cfg!(target_os = "macos") {
        crate::apple::run(&["--test".into()])?;
    }
    Ok(())
}
